#!/usr/bin/env node
// ARCHIVE.SYS build: src/ (template + css + js) + content/ (disks)  ->  docs/index.html (one fast file)
//   node tools/build.mjs           build once
//   node tools/build.mjs --watch   rebuild on every save in src/ or content/
//   node tools/build.mjs --check   validate only, write nothing
import fs from "node:fs";
import path from "node:path";
import { ROOT, CONTENT, INDEX, readContent, validate, inject } from "./cms-lib.mjs";
const SRC = path.join(ROOT, "src");
const HEADER =
  "<!-- GENERATED by tools/build.mjs from src/ + content/ — do not edit this file; edit src/ or content/ and rebuild -->\n";

export function assemble() {
  const man = JSON.parse(fs.readFileSync(path.join(SRC, "manifest.json"), "utf8"));
  const read = (rel) => fs.readFileSync(path.join(SRC, rel), "utf8");
  const tpl = read("index.template.html");
  // The sources are indented for reading; the shipped page drops the leading indentation
  // of every CSS/JS line and blank lines (safe: the sources use no multi-line strings or template literals).
  const unindent = (code) => code.replace(/^[ \t]+/gm, "").replace(/\n{2,}/g, "\n");
  const join = (list) => unindent(list.map(read).join("")).replace(/\n$/, "");
  return tpl
    .replace("@@FONTS@@", () => read("css/fonts.css").replace(/\n$/, ""))
    .replace("@@CSS@@", () => join(man.css))
    .replace("@@JS@@", () => join(man.js));
}
export function build({ write = true, header = true } = {}) {
  const cats = readContent();
  const { errs, warns } = validate(cats);
  warns.forEach((w) => console.log("  warn  " + w));
  if (errs.length) {
    errs.forEach((e) => console.log("  ERROR " + e));
    throw new Error(`${errs.length} content error(s) — index.html NOT changed (last good build stays live)`);
  }
  // The shipped page drops source indentation everywhere (the only <pre> is empty and filled by JS).
  let html = inject(assemble(), cats).replace(/^[ \t]+/gm, "");
  if (header) html = html.replace(/^<!DOCTYPE html>\n/i, (m) => m + HEADER);
  if (write) {
    const tmp = INDEX + ".tmp";
    fs.writeFileSync(tmp, html);
    fs.renameSync(tmp, INDEX);
  }
  const n = (c) => c.items.reduce((s, it) => s + (it.folder ? n(it) : 1), 0);
  console.log(
    `  built ${path.relative(process.cwd(), INDEX) || "index.html"}: ${cats.map((c) => `${c.id}(${n(c)})`).join(" ")} · ${(Buffer.byteLength(html) / 1024).toFixed(1)} KB`
  );
  return html;
}

const isMain =
  process.argv[1] && path.resolve(process.argv[1]) === path.resolve(new URL(import.meta.url).pathname);
if (isMain) {
  const arg = process.argv[2] || "";
  const once = () => {
    try {
      build({ write: arg !== "--check" });
      return true;
    } catch (e) {
      console.log("  " + e.message);
      return false;
    }
  };
  const ok = once();
  if (arg === "--watch") {
    // polling (portable; inotify is not reliable everywhere): a 40-file stat every second costs nothing
    const sig = () => {
      const out = [];
      const walk = (d) => {
        for (const e of fs.readdirSync(d, { withFileTypes: true })) {
          if (e.name.startsWith(".") || e.name.endsWith(".tmp")) continue;
          const f = path.join(d, e.name);
          if (e.isDirectory()) walk(f);
          else {
            const st = fs.statSync(f);
            out.push(f + ":" + st.mtimeMs + ":" + st.size);
          }
        }
      };
      try {
        walk(CONTENT);
        walk(SRC);
      } catch (e) {
        return "err";
      }
      return out.sort().join("|");
    };
    let last = sig();
    setInterval(() => {
      const now = sig();
      if (now !== last) {
        last = now;
        console.log(new Date().toISOString().slice(11, 19) + " change detected");
        once();
      }
    }, 1000);
    console.log("  watching content/ and src/ (every 1 s) …");
  } else process.exit(ok ? 0 : 1);
}
